    SmmActivityParentLinkTable  smmActivityParentLinkTable;

    KCS_KBVBuildingProjectID    kcs_KBVBuildingProjectID;

    KCS_KBVRelationsToBV        kcs_KBVRelationsToBV;
    KCS_KBVRelations            kcs_KBVRelations;

    select firstonly smmActivityParentLinkTable
    where   smmActivityParentLinkTable.ActivityNumber   == this.ActivityNumber
        &&  smmActivityParentLinkTable.ParentType       == smmActivityParentType::BuildingProject;

    //bei Kontakt auch GB anzeigen
    if(smmActivityParentLinkTable.ParentType == smmActivityParentType::BuildingProject)
    {
        kcs_KBVBuildingProjectID = smmActivityParentLinkTable.linkedParentId();

        select firstonly kcs_KBVRelationsToBV
        order by kcs_KBVRelations.KCS_KBVSalesPriority desc
        where   kcs_KBVRelationsToBV.KCS_KBVBuildingProjectID == kcs_KBVBuildingProjectID
