/// <summary>
///    AVA <c>avaDisplayLinkedParentName</c> method.
/// </summary>
/// <returns>
///    <c>Name</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display Name avaDisplayLinkedParentName()
{
    Name                        retVal;
    Name                        locName;

    //smmActivityParentLinkId     locsmmActivityParentLinkId;

    SmmActivityParentLinkTable  locSmmActivityParentLinkTable;

    ContactPersonId             locContactPersonId;
    ContactPerson               locContactPerson;

    DirPartyTable               locDirPartyTable;

    locSmmActivityParentLinkTable = smmActivityParentLinkTable::findPrimaryLink(this.ActivityNumber);

    if(locSmmActivityParentLinkTable.RecId)
    {
        //bei Kontakt auch GB anzeigen
        if(locSmmActivityParentLinkTable.ParentType == smmActivityParentType::ContactPerson)
        {
            /* 2009
            select contactPersonId, OrgPartyId
            from    contactPerson
            where   contactPerson.ContactPersonId == locContactPersonId;

            name = DirPartyTable::findRec(contactPerson.OrgPartyId).Name + ': ';
            */

            locContactPersonId = locSmmActivityParentLinkTable.linkedParentId();

            locContactPerson    = ContactPerson::find(locContactPersonId);

            retVal              = locContactPerson.partyName() + ': ';
        }
        switch (locSmmActivityParentLinkTable.ParentType)
        {
            case smmActivityParentType::Person :
            case smmActivityParentType::Organization :
                locDirPartyTable    =  DirPartyTable::findRec(locSmmActivityParentLinkTable.RefRecId);
                locName             = locDirPartyTable.Name;
                break;

            case smmActivityParentType::ContactPerson:
                locName             = locContactPerson.personName();
                break;
        }
        retVal += locName; // 2009 locSmmActivityParentLinkTable.linkedParentName();
    }

    return retVal;

    /*
    //  1.0 : NDX/Heckk/05.10.2011 - Erste Version

    //BP deviation documented
    display Name NDX_linkedParentName()
    {

        SmmActivityParentLinkTable  smmActivityParentLinkTable;
        ContactPerson               contactPerson;

        ContactPersonId             contactPersonId;
        Name                        name='';
        ;

        select firstonly    smmActivityParentLinkTable
            where           smmActivityParentLinkTable.ActivityNumber == this.ActivityNumber &&
                            smmActivityParentLinkTable.PrimaryLink;

        //bei Kontakt auch GB anzeigen
        if(smmActivityParentLinkTable.ParentType == smmActivityParentType::ContactPerson)
        {
            contactPersonId = smmActivityParentLinkTable.linkedParentId();

            select contactPersonId, OrgPartyId from contactPerson
                where contactPerson.ContactPersonId == contactPersonId;

            name = DirPartyTable::find(contactPerson.OrgPartyId).Name + ': ';
        }

        return name + smmActivityParentLinkTable.linkedParentName();
    */
    /*
        // To get primary name for current activity
        //BP Deviation documented
        display smmActivityParentName linkedParentName()
        {
        fieldId                 fieldId;
        DictTable               dictTable;
        DictField               dictField;
        Common                  common;
        ;

        if (!this.RecId)
        {
        return '';
        }

        fieldId = smmActivityParentLink::parentType2FieldName(this.ParentType);
        dictTable = new DictTable(this.RefTableId);
        common = dictTable.makeRecord();
        if (dictTable && dictTable.rights() >= AccessType::View)
        {
        dictField = new DictField(common.TableId, fieldId);
        if (dictField && dictField.rights() >= AccessType::View)
        {
        select common where common.RecId == this.RefRecId;
        }
        }
        return (common.RecId ? common.(fieldId) : '');
        }
    */

