/// <summary>
///    AVA <c>avaInitFromKCS_KBVBuildingProjectTable</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectTable">
///    <c>KCS_KBVBuildingProjectTable</c> as type
/// </param>
/// <param name="_smmResponsibleWorker">
///    <c>HcmWorkerRecId</c> as type
/// </param>
void avaInitFromKCS_KBVBuildingProjectTable(KCS_KBVBuildingProjectTable _kcs_KBVBuildingProjectTable, HcmWorkerRecId _smmResponsibleWorker) // smmResponsibilityId _kcsSmmResponsibilityId = '')
{
    KCS_KBVParameters                   kcs_KBVParameters;
    smmActivityTypeGroup                smmActivityTypeGroup;
    smmActivityParentRefRecId           parentRefRecId;
    smmActivityParentType               parentType;
    DirPartyView                        dirPartyView;
    KCS_KBVRelationsToBV                kcs_KBVRelationsToBV;
    DirPartyTable                       dirPartyTable;
    smmBusRelTable                      smmBusRelTable;
    CustTable                           custTable;
    ContactPerson                       contactPerson;

    kcs_KBVParameters = KCS_KBVParameters::find();
    this.initValue(kcs_KBVParameters.KCS_KBVActivityCategory);

    this.ResponsibleWorker  = _smmResponsibleWorker;
    this.TypeId             = kcs_KBVParameters.KCS_KBVActivityTypeId;

    select firstOnly smmActivityTypeGroup 
    where smmActivityTypeGroup.TypeId == this.TypeId;
    if (smmActivityTypeGroup.RecId)
    {
        this.Purpose = strfmt("@NDX:NXAP1SpaceP2SpaceP3",   smmActivityTypeGroup.Description,
                                                            _kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                            _kcs_KBVBuildingProjectTable.KCS_KBVSubject);
    }

    this.StartDateTime = DateTimeUtil::getSystemDateTime();

    this.initFromWorkerTable(this.ResponsibleWorker);

    this.avaSetEndDateTimeFromBP(_kcs_KBVBuildingProjectTable);

    if (this.ReminderMinutes > 0)
    {
        this.ReminderActive     = NoYes::Yes;
    }
    else
    {
        this.ReminderActive     = NoYes::No;
    }

    kcs_KBVRelationsToBV = AVAKBVHelperClass::getHighestRelation(_kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
    if (kcs_KBVRelationsToBV.RecId)
    {
        dirPartyTable = DirPartyTable::findRec(kcs_KBVRelationsToBV.DirPartyId);
        if (dirPartyTable.RecId)
        {
            // Customer
            select firstonly dirPartyView 
            where   dirPartyView.Party              == dirPartyTable.RecId
                &&  dirPartyView.unionAllBranchId   == 1;
            if (dirPartyView)
            {
                custTable = CustTable::findByPartyRecId(dirPartyView.Party);
                if (custTable)
                {
                    parentType      = smmActivityParentType::Customer;
                    parentRefRecId  = custTable.RecId;
                    this.insertParentLink(parentType, parentRefRecId, false);
                }
            }
            else
            {
                // BusRel
                select firstonly dirPartyView
                where   dirPartyView.Party              == dirPartyTable.RecId
                    &&  dirPartyView.unionAllBranchId   == 3;
                if (dirPartyView)
                {
                    smmBusRelTable = smmBusRelTable::findByParty(dirPartyView.Party);
                    if (smmBusRelTable)
                    {
                        parentType = smmActivityParentType::BusRel;
                        parentRefRecId = smmBusRelTable.RecId;
                        this.insertParentLink(parentType, parentRefRecId, false);
                    }
                }
            }
        }

        // ContactPerson
        dirPartyTable = DirPartyTable::findRec(ContactPerson::find(kcs_KBVRelationsToBV.ContactPersonId).Party);
        if (dirPartyTable)
        {
            contactPerson = ContactPerson::findByPartyRecId(dirPartyTable.RecId);
            if (contactPerson)
            {
                parentType      = smmActivityParentType::ContactPerson;
                parentRefRecId  = contactPerson.RecId;
                this.insertParentLink(parentType, parentRefRecId, false);
            }
            else
            {
                parentType      = smmActivityParentType::Person;
                parentRefRecId  = dirPartyTable.RecId;
                this.insertParentLink(parentType, parentRefRecId, false);
            }
        }
    }

    _kcs_KBVBuildingProjectTable.selectForUpdate(true);
    //_kcs_KBVBuildingProjectTable.KCS_KBVReminderDate = DateTimeUtil::date(this.EndDateTime);
    _kcs_KBVBuildingProjectTable.update();
}

/// <summary>
///    AVA <c>avaInitFromCommon</c> method.
/// </summary>
/// <param name="_table">
///    <c>Common</c> as type
/// </param>
/// <param name="_responsibleWorker">
///    <c>HcmWorkerRecId</c> as type
/// </param>
void avaInitFromCommon(Common _table, HcmWorkerRecId _responsibleWorker)
{
    smmActivityParentRefRecId   parentRefRecId;
    smmActivityParentType       parentType;

    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    // Initalize activity based on the type of record
    switch (_table.TableId)
    {
        case tableNum(KCS_KBVBuildingProjectTable):
            locKCS_KBVBuildingProjectTable = _table;
            this.avaInitFromKCS_KBVBuildingProjectTable(locKCS_KBVBuildingProjectTable, _responsibleWorker);
            parentType      = smmActivityParentType::BuildingProject;
            parentRefRecId  = _table.RecId;

            // Insert link to parent
            this.insertParentLink(parentType, parentRefRecId, true, _table);
            break;

        default:
            this.initFromCommon(_table);
    }

}

/// <summary>
///    AVA <c>avaSetEndDateTimeFromBP</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectTable">
///    <c>KCS_KBVBuildingProjectTable</c> as type
/// </param>
public void avaSetEndDateTimeFromBP(KCS_KBVBuildingProjectTable _kcs_KBVBuildingProjectTable)
{
    smmQuotationProbabilityGroup        locsmmQuotationProbabilityGroup;
    int                                 daysToAdd;
    KCS_KBVParameters                   locKCS_KBVParameters;
    utcdatetime                         LocUtcdatetime;

    if(_kcs_KBVBuildingProjectTable.RecId)
    {

        locsmmQuotationProbabilityGroup = smmQuotationProbabilityGroup::find(_kcs_KBVBuildingProjectTable.smmQuotationProbabilityId);

        // check existing probability group days to add
        if(_kcs_KBVBuildingProjectTable.smmQuotationProbabilityId)
        {
            locsmmQuotationProbabilityGroup = smmQuotationProbabilityGroup::find(_kcs_KBVBuildingProjectTable.smmQuotationProbabilityId);
            if(locsmmQuotationProbabilityGroup.RecId && locsmmQuotationProbabilityGroup.KCS_KBVActivityDays)
            {
                daysToAdd = locsmmQuotationProbabilityGroup.KCS_KBVActivityDays;
            }
        }
        // check if building project has submission date defined and use days after submission
        else if(_kcs_KBVBuildingProjectTable.KCS_KBVSubmissionDate != dateNull())
        {
            this.EndDateTime        = DateTimeUtil::newDateTime(_kcs_KBVBuildingProjectTable.KCS_KBVSubmissionDate, 0);
            locKCS_KBVParameters    = KCS_KBVParameters::find();
            daysToAdd               = locKCS_KBVParameters.AVAKBVDaysAfterSubmission;
        }
        // default using parameter settings for days to add
        else
        {
            locKCS_KBVParameters    = KCS_KBVParameters::find();
            daysToAdd               = locKCS_KBVParameters.KCS_KBVActivityDays;
        }
        if(daysToAdd)
        {
            this.EndDateTime        = DateTimeUtil::addDays(this.EndDateTime, daysToAdd);
        }
        if(     this.StartDateTime // != utcDateTimeNull()
            &&  this.StartDateTime > this.EndDateTime   )
        {
            daysToAdd               = locKCS_KBVParameters.KCS_KBVActivityDays;
            this.EndDateTime        = this.StartDateTime;
            this.EndDateTime        = DateTimeUtil::addDays(this.EndDateTime, daysToAdd);
        }
        if(this.EndDateTime) // != utcDateTimeNull())
        {
            locUtcdatetime = DateTimeUtil::minValue();
            if(this.EndDateTime  < locUtcdatetime )
            {
                daysToAdd           = 1;
                this.EndDateTime    = locUtcdatetime;
                this.EndDateTime    = DateTimeUtil::addDays(this.EndDateTime, daysToAdd);
            }
        }

    }
}

/// <summary>
///     AVA <c>avaGetResponsibleFieldWorker</c> method.
///     AVA - Schneider 28.05.2024
/// </summary>
/// <param name="_planned">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>HCMWorker</c> as return value
/// </returns>
public HCMWorker avaGetResponsibleFieldWorker(boolean _planned = false)
{
    HCMWorker                       retVal;

    smmResponsibilityId             locsmmResponsibilityId;
    KCS_KBVActivitiesForBP          locKCS_KBVActivitiesForBP;
    KCS_KBVResponsibilitiesTable    locKCS_KBVResponsibilitiesTable;
    smmWorker                       locsmmWorker;

    locsmmResponsibilityId = smmResponsibilityGroup::avaResponsibleFieldWorkerResponsibilityId(); // ADM
    if(locsmmResponsibilityId)
    {
        select firstOnly locKCS_KBVActivitiesForBP
        where  locKCS_KBVActivitiesForBP.smmActivityNumber == this.ActivityNumber;

        if(     locKCS_KBVActivitiesForBP.RecId
            &&  locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID  )
        {
            locKCS_KBVResponsibilitiesTable = KCS_KBVResponsibilitiesTable::find(locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID, locsmmResponsibilityId);

            if(locKCS_KBVResponsibilitiesTable.RecId)
            {
                if(_planned)
                {
                    if(locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate == dateNull())
                    {
                        locsmmWorker = locKCS_KBVResponsibilitiesTable.smmWorker;
                    }
                }
                else
                {
                    locsmmWorker = locKCS_KBVResponsibilitiesTable.smmWorker;
                }
            }
        }
    }

    if(locsmmWorker)
    {
        retVal = HcmWorker::find(locsmmWorker);
    }

    return retVal;
}

